const fs = require('fs');
const defaults = {
  hook_intensity: 0.7,
  hook_duration_seconds: 15,
  question_frequency: 0.3,
  first_question_time_seconds: 45,
  pacing: "medium",
  psychological_pressure: 0.5,
  topic_breadth: "balanced"
};

let params = defaults;

try {
  if (fs.existsSync('./control_params.json')) {
    const data = JSON.parse(fs.readFileSync('./control_params.json', 'utf8'));
    params = { ...defaults, ...data };
  }
} catch (error) {
  params = defaults;
}

return [{ json: params }];

// RSS-based topic selection

// n8n gives one item per RSS entry
// We will transform each item into a usable topic

const title = $json.title;
const snippet = $json.contentSnippet || '';

// Basic validation
if (!title) {
  return [];
}

// Simple heuristic scoring (can improve later)
let score = 0;

// Strong psychology keywords
const keywords = [
  'dark',
  'manipulate',
  'manipulation',
  'control',
  'personality',
  'traits',
  'psychology',
  'behavior',
  'toxic'
];

// Score based on keyword presence
keywords.forEach(keyword => {
  if (title.toLowerCase().includes(keyword)) {
    score += 1;
  }
});

// Prefer titles that sound personal / emotional
if (title.toLowerCase().includes('people')) score += 0.5;
if (title.toLowerCase().includes('you')) score += 1;
if (title.length < 90) score += 0.5;

// Return normalized topic object
return [
  {
    json: {
      topic: title,
      score,
      source: 'rss',
      link: $json.link,
      published_at: $json.pubDate
    }
  }
];

