// Pick the highest-scoring topic so downstream nodes use one clear winner.
const items = $input.all();

if (!items.length) {
  return [];
}

let best = items[0];
for (const item of items) {
  if ((item.json.score || 0) > (best.json.score || 0)) {
    best = item;
  }
}

return [{
  json: {
    topic: best.json.topic,
    score: best.json.score,
    source: best.json.source,
    link: best.json.link,
    published_at: best.json.published_at
  }
}];

