// Summarize research headlines for prompt grounding.
const items = $input.all();
const headlines = items
  .map((item, index) => {
    const title = item.json?.title || '';
    const link = item.json?.link || '';
    return title ? `${index + 1}. ${title} (${link})` : null;
  })
  .filter(Boolean)
  .slice(0, 8);

return [{
  json: {
    topic: $input.first()?.json?.topic || '',
    research_headlines: headlines.join('\n')
  }
}];

// Fetch analytics from a local file if available, otherwise fallback to mock data.
const fs = require('fs');

let analytics;
try {
  if (fs.existsSync('./analytics.json')) {
    analytics = JSON.parse(fs.readFileSync('./analytics.json', 'utf8'));
  }
} catch (error) {
  analytics = null;
}

if (!analytics) {
  analytics = {
    views: Math.floor(Math.random() * 1000) + 100,
    averageViewDuration: Math.floor(Math.random() * 120) + 30,
    retention_30s: Math.random().toFixed(2),
    retention_60s: Math.random().toFixed(2)
  };
}

return [{ json: analytics }];

