// Save new control parameters for next run
const fs = require('fs');

let newParams = $json;
const content = $json?.choices?.[0]?.message?.content;

if (content) {
  try {
    newParams = JSON.parse(content);
  } catch (error) {
    newParams = { raw_response: content };
  }
}

// Add timestamp for tracking
newParams.last_updated = new Date().toISOString();

fs.writeFileSync('./control_params.json', JSON.stringify(newParams, null, 2));
return [{ json: { status: 'parameters_saved', params: newParams } }];

