// Clean RSS topic by removing source names like "- binghamton.edu"
const rawTopic = $json.topic;

if (!rawTopic) {
  return [];
}

const cleanedTopic = rawTopic.replace(/\s-\s.*$/, '');

return [
  {
    json: {
      topic: cleanedTopic,
      original_topic: rawTopic
    }
  }
];

// 1️⃣ Get raw Gemini text
const raw = $json.candidates[0].content.parts[0].text
  .replace(/```json|```/g, '')
  .trim();

// 2️⃣ Parse JSON safely
let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse Gemini JSON');
}

if (!Array.isArray(data.script)) {
  throw new Error('Gemini output missing script array');
}

// 3️⃣ HARD-SAFE Pixabay query sanitizer
function sanitizeQuery(input) {
  if (!input || typeof input !== 'string') {
    return 'dark scene';
  }

  return input
    .toLowerCase()
    .replace(/[,.;:]/g, ' ')   // remove commas & punctuation
    .replace(/\s+/g, ' ')      // normalize spaces
    .trim()
    .split(' ')
    .slice(0, 3)               // MAX 3 WORDS (Pixabay-safe)
    .join(' ');
}

// 4️⃣ Emit ONE ITEM PER SCENE (loop-ready)
return data.script.map(scene => ({
  json: {
    scene_index: scene.scene_index,
    narration: scene.narration,
    video_query: sanitizeQuery(scene.visual_query),
    audio_path: `/tmp/audio_${scene.scene_index}.wav`,
    video_raw_path: `/tmp/video_raw_${scene.scene_index}.mp4`,
    scene_final_path: `/tmp/scene_final_${scene.scene_index}.mp4`
  }
}));

// 1️⃣ Get the TTS output (which contains the duration)
const ttsOutput = $input.item.json;

// 2️⃣ Verify we have duration from TTS
if (!ttsOutput.duration || ttsOutput.duration === "0") {
  console.warn("TTS node missing duration. Using fallback of 5.0 seconds");
  ttsOutput.duration = "5.0";
}

// 3️⃣ Get the original loop item (for scene context)
