// 4️⃣ Preserve ALL required data for FFMPEG
return [{
  json: {
    audio_path: loopItem.audio_path,
    scene_index: loopItem.scene_index,
    scene_final_path: loopItem.scene_final_path,
    video_query: loopItem.video_query,
    duration: ttsOutput.duration,  // Use duration from TTS output
