const data = $getWorkflowStaticData('global');

if (!data.seen) {
  data.seen = {};
}

// 1. Remove already-used topics
const freshItems = items.filter(item => {
  const key = item.json.guid || item.json.title;
  return !data.seen[key];
});

// 2. Shuffle randomly (Fisher–Yates)
for (let i = freshItems.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [freshItems[i], freshItems[j]] = [freshItems[j], freshItems[i]];
}

// 3. Pick max 10 topics
const selected = freshItems.slice(0, 10);

// 4. Lock them so they never appear again
for (const item of selected) {
  const key = item.json.guid || item.json.title;
  data.seen[key] = true;
}

return selected;
